const SPACE: &str = r"\x09-\x0D\x1C-\x20\x{85}\x{A0}\x{1680}\x{2000}-\x{200A}\x{2028}\x{2029}\x{202F}\x{205F}\x{3000}";
struct Patterns {
    fence: Regex,
    command: Regex,
    environment: Regex,
    inline: Regex,
    readme: Regex,
    condition: Regex,
    procedural: Regex,
    heading: Regex,
    bullet: Regex,
    script: Regex,
}
impl Patterns {
    fn new() -> io::Result<Self> {
        let re = |p: &str| {
            Regex::new(&p.replace(r"\s", &format!("[{SPACE}]"))).map_err(io::Error::other)
        };
        let tokens = r"(?:python(?:\d+(?:\.\d+)*)?|pytest|uv(?:[ \t]+run)?|pip(?:\d+)?|npm|npx|node|cargo|go|git|make|bash|sh|zsh|fish|powershell|pwsh|systemctl|journalctl|curl|wget|jq|rg|grep|sed|awk|find|chmod|mkdir|cp|mv|rm|docker|podman|env)";
        // Consumed boundary replaces Python lookahead. The special source
        // branch only needs the following argument's first character.
        let token = format!(r#"(?:{tokens}(?:[ \t`]|$)|source[ \t]+[./~$"'])"#);
        let assignment = r#"(?:[A-Z_][A-Z0-9_]*=(?:"[^"]*"|'[^']*'|[^\s]+)[ \t]+)"#;
        let lead = r"^[ \t]*(?:(?:[-*+][ \t]+|\d+[.)][ \t]+))?(?:`)?";
        Ok(Self {
            fence: re(r"^ {0,3}```")?,
            command: re(&format!(r"(?i){lead}(?:\$[ \t]+)?{assignment}*{token}"))?,
            environment: re(&format!(r"(?i){lead}{assignment}+{token}"))?,
            inline: re(&format!(r"(?i)^(?:\$[ \t]+)?{assignment}*{token}"))?,
            readme: re(r"(?i)(?:read|open|review|start\s+with|use)")?,
            condition: re(
                r"(?i)(?:(?:when|if|where|after|only|touched)|(?:as|when|if)\s+needed|(?:relevant|selected|known|target|named))",
            )?,
            procedural: re(
                r"(?i)^#{1,6}\s+(?:validation|verify|verification|checks?|testing|procedure|smoke)(?:\s|$)",
            )?,
            heading: re(r"^(#{1,6})\s+(.+?)\s*$")?,
            bullet: re(r"^(\s*)(?:[-*+]|\d+[.)])\s+")?,
            script: re(r#"((?:scripts|mechanics|\.agents)/[^\s`)'\"]+\.py)"#)?,
        })
    }
}

fn fold_ascii(text: &str) -> String {
    text.chars()
        .map(|c| match c {
            'İ' | 'ı' => 'i',
            'ſ' => 's',
            'K' => 'k',
            _ => c,
        })
        .collect()
}
fn strip(text: &str) -> &str {
    text.trim_matches(python_space)
}
fn normalize(text: &str) -> io::Result<String> {
    Ok(lower(text)?
        .split(python_space)
        .filter(|s| !s.is_empty())
        .collect::<Vec<_>>()
        .join(" "))
}
fn python_repr(text: &str) -> String {
    let quote = if text.contains('\'') && !text.contains('"') {
        '"'
    } else {
        '\''
    };
    let mut out = String::new();
    out.push(quote);
    for c in text.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c == quote => {
                out.push('\\');
                out.push(c);
            }
            c if !python_printable(c) => {
                let point = c as u32;
                out.push_str(&if point < 256 {
                    format!("\\x{point:02x}")
                } else if point <= 0xffff {
                    format!("\\u{point:04x}")
                } else {
                    format!("\\U{point:08x}")
                });
            }
            c => out.push(c),
        }
    }
    out.push(quote);
    out
}
fn issue(issues: &mut Vec<Issue>, path: &str, message: impl Into<String>) -> io::Result<()> {
    let message = message.into();
    let previous = issues
        .iter()
        .try_fold(0usize, |total, (path, message)| {
            total.checked_add(path.len() + message.len() + 5)
        })
        .ok_or_else(|| invalid("route diagnostic byte overflow"))?;
    if issues.len() >= MAX_ISSUES
        || message.len() > 8192
        || previous.saturating_add(path.len() + message.len() + 5) > MAX_OUTPUT
    {
        return Err(invalid("route diagnostic bound exceeded"));
    }
    issues.push((path.into(), message));
    Ok(())
}
fn procedural_issues(
    path: &str,
    text: &str,
    inherited_validation: bool,
    p: &Patterns,
    issues: &mut Vec<Issue>,
) -> io::Result<()> {
    let lines = splitlines(text);
    let mut seen = BTreeSet::new();
    for (index, line) in lines.iter().enumerate() {
        let number = index + 1;
        let folded = fold_ascii(line);
        if p.fence.is_match(line) {
            issue(
                issues,
                path,
                format!("line {number}: fenced procedure/example is not allowed"),
            )?;
        }
        if p.environment.is_match(&folded) {
            issue(
                issues,
                path,
                format!("line {number}: environment-assignment command is not allowed"),
            )?;
        } else if p.command.is_match(&folded) {
            issue(
                issues,
                path,
                format!("line {number}: runnable command line is not allowed"),
            )?;
        }
        // Python's pattern can start at every backtick, including the closing
        // backtick of a preceding span. Keep each adjacent delimiter pair.
        let ticks: Vec<_> = folded.match_indices('`').map(|(i, _)| i).collect();
        if ticks
            .windows(2)
            .any(|pair| p.inline.is_match(&folded[pair[0] + 1..pair[1]]))
        {
            issue(
                issues,
                path,
                format!("line {number}: inline runnable command is not allowed"),
            )?;
        }
        if let Some(h) = p.heading.captures(line) {
            if !seen.insert((h[1].len(), normalize(&h[2])?)) {
                issue(
                    issues,
                    path,
                    format!("line {number}: repeated heading {}", python_repr(&h[2])),
                )?;
            }
        }
    }
    for (index, line) in lines.iter().enumerate() {
        if !p.procedural.is_match(&fold_ascii(line)) {
            continue;
        }
        let mut end = index + 1;
        while end < lines.len() && !p.heading.is_match(lines[end]) {
            end += 1;
        }
        if !lines[index + 1..end].iter().any(|s| !strip(s).is_empty()) {
            issue(
                issues,
                path,
                format!(
                    "line {}: empty procedural section {}",
                    index + 1,
                    python_repr(strip(line.trim_start_matches('#')))
                ),
            )?;
        }
    }
    for (index, line) in lines.iter().enumerate() {
        if !strip(line).ends_with(':') {
            continue;
        }
        let mut next = index + 1;
        while next < lines.len() && strip(lines[next]).is_empty() {
            next += 1;
        }
        if next == lines.len() {
            issue(
                issues,
                path,
                format!("line {}: orphan extraction lead-in before EOF", index + 1),
            )?;
            continue;
        }
        if p.heading.is_match(lines[next]) || p.fence.is_match(lines[next]) {
            issue(
                issues,
                path,
                format!(
                    "line {}: orphan extraction lead-in before structure",
                    index + 1
                ),
            )?;
        }
        if strip(lines[next]).ends_with(':') {
            issue(
                issues,
                path,
                format!("line {}: stacked colon lead-ins are not allowed", index + 1),
            )?;
        }
        if let (Some(a), Some(b)) = (p.bullet.captures(line), p.bullet.captures(lines[next])) {
            if a[1].chars().count() == b[1].chars().count() {
                issue(
                    issues,
                    path,
                    format!("line {}: same-level bullet lead-in has no body", index + 1),
                )?;
            }
        }
    }
    for (index, line) in lines.iter().enumerate() {
        let folded = fold_ascii(line);
        if has_readme_route(p, &folded) && !word_match(&p.condition, &folded) {
            issue(
                issues,
                path,
                format!("line {}: unconditional README inventory", index + 1),
            )?;
        }
    }
    for (index, line) in lines.iter().enumerate() {
        let Some(h) = p.heading.captures(line) else {
            continue;
        };
        if !README_INVENTORY_HEADINGS.contains(&strip(&lower(&h[2])?)) {
            continue;
        }
        let mut end = index + 1;
        while end < lines.len() && !p.heading.is_match(lines[end]) {
            end += 1;
        }
        let section = &lines[index + 1..end];
        let mut includes_readme = false;
        for item in section {
            includes_readme |= lower(item)?.contains("readme");
        }
        if includes_readme
            && !section
                .iter()
                .any(|s| word_match(&p.condition, &fold_ascii(s)))
        {
            issue(
                issues,
                path,
                format!("line {}: unconditional README inventory section", index + 1),
            )?;
        }
    }
    if !inherited_validation && !text.contains("VALIDATION.md") {
        issue(issues, path, "missing nearest validation route")?;
    }
    Ok(())
}
fn card_issues(
    s: &mut RouteSources,
    path: &str,
    text: &str,
    issues: &mut Vec<Issue>,
) -> io::Result<()> {
    if !strip(text).starts_with("# AGENTS.md") {
        issue(issues, path, "missing '# AGENTS.md' heading")?;
    }
    let compact = !splitlines(text).iter().any(|s| s.starts_with("## "))
        && (text.contains("This file applies") || text.contains("This card applies"));
    if !compact {
        for (headings, message) in [
            (ROLE_HEADINGS, "missing role or local scope heading"),
            (
                ORIENTATION_HEADINGS,
                "missing read/apply orientation heading",
            ),
            (
                ROUTE_HEADINGS,
                "missing route, boundary, or validation heading",
            ),
        ] {
            if !headings.iter().any(|h| text.contains(h)) {
                issue(issues, path, message)?;
            }
        }
    }
    for marker in BANNED_ROUTE_SECTION_MARKERS {
        if text.contains(marker) {
            issue(
                issues,
                path,
                format!("use Operating Card/Boundary Routes instead of {marker}"),
            )?;
        }
    }
    if text.contains("## Operating Card") {
        let mut fields = BTreeSet::new();
        for line in splitlines(text) {
            let line = strip(line);
            if !line.starts_with('|') || line.contains("---") {
                continue;
            }
            let cells: Vec<_> = line
                .trim_matches('|')
                .split('|')
                .map(|c| lower(strip(c).trim_matches('`')))
                .collect::<io::Result<Vec<_>>>()?;
            if cells.len() >= 2 && cells[0] != "field" {
                fields.insert(cells[0].clone());
            }
        }
        for field in ["input", "output", "owner", "next route"] {
            if !fields.contains(field) {
                issue(
                    issues,
                    path,
                    format!("Operating Card missing field: {field}"),
                )?;
            }
        }
        if !["check", "validation", "tools"]
            .iter()
            .any(|v| fields.contains(*v))
        {
            issue(
                issues,
                path,
                "Operating Card needs check, validation, or tools field",
            )?;
        }
    }
    if let Some((_, refs)) = REQUIRED_REFERENCES.iter().find(|(name, _)| *name == path) {
        for reference in *refs {
            if !text.contains(reference) {
                issue(
                    issues,
                    path,
                    format!("missing stable route reference: {reference}"),
                )?;
                continue;
            }
            if reference.ends_with('/')
                || matches!(*reference, "TOS-D-####" | "## Index Metadata" | "aoa-evals")
                || (!reference.contains('/') && !reference.starts_with('.'))
                || reference.starts_with("python ")
            {
                continue;
            }
            if !s.exists(reference)? {
                issue(
                    issues,
                    path,
                    format!("stable route reference points to missing path: {reference}"),
                )?;
            }
        }
    }
    Ok(())
}
fn inventory_issues(
    s: &mut RouteSources,
    inventory: &Value,
    cards: &[String],
    tracked: Option<&BTreeSet<String>>,
    issues: &mut Vec<Issue>,
) -> io::Result<()> {
    let required = [
        "schema_version",
        "owner_repo",
        "owner_surface",
        "validator",
        "currentness",
        "harness",
        "route_card_discovery",
        "influencing_surfaces",
        "context_budget",
        "scope_duplication_policy",
        "task_routes",
    ];
    let mut missing: Vec<_> = required
        .iter()
        .filter(|k| inventory.get(**k).is_none())
        .copied()
        .collect();
    missing.sort();
    if !missing.is_empty() {
        issue(
            issues,
            INVENTORY,
            format!("inventory missing fields: {}", missing.join(", ")),
        )?;
        return Ok(());
    }
    if inventory["schema_version"] != "tos_agents_route_inventory_v1" {
        issue(issues, INVENTORY, "unsupported route inventory schema")?;
    }
    for key in ["owner_surface", "validator", "currentness", "harness"] {
        let value = field(inventory, key)?;
        if !s.is_file(value)? {
            issue(
                issues,
                INVENTORY,
                format!("inventory reference points to missing path: {value}"),
            )?;
        }
    }
    let discovered: BTreeSet<_> = cards.iter().cloned().collect();
    let discovery = &inventory["route_card_discovery"];
    if let Some(tracked) = tracked {
        for value in tracked.difference(&discovered) {
            issue(
                issues,
                value,
                "tracked AGENTS.md is outside route-card inventory roots",
            )?;
        }
        for value in discovered.difference(tracked) {
            issue(issues, value, "discovered AGENTS.md is not tracked")?;
        }
    }
    if !strings(&discovery["root_cards"])?
        .iter()
        .any(|s| s == "AGENTS.md")
    {
        issue(
            issues,
            INVENTORY,
            "route inventory must name the root AGENTS.md",
        )?;
    }
    if !strings(&discovery["route_roots"])?
        .iter()
        .any(|s| s == ".github")
    {
        issue(
            issues,
            INVENTORY,
            "route inventory must include .github for tracked card parity",
        )?;
    }
    for card in cards {
        let ancestry = stack(card, false, &discovered, true);
        if ancestry.first().map(String::as_str) != Some("AGENTS.md") {
            issue(
                issues,
                card,
                "inheritance stack must begin at root AGENTS.md",
            )?;
        }
    }
    for card in cards {
        let ancestry = stack(card, false, &discovered, true);
        for ancestor in &ancestry[..ancestry.len().saturating_sub(1)] {
            if s.source(card)?.unwrap().raw == s.source(ancestor)?.unwrap().raw {
                issue(
                    issues,
                    card,
                    format!("byte-identical nested card duplicates {ancestor}"),
                )?;
            }
        }
    }
    for entry in discovery["preserved_non_cards"]
        .as_array()
        .ok_or_else(|| invalid("expected preserved array"))?
    {
        let value = entry.get("path").and_then(Value::as_str).unwrap_or("");
        if !s.is_file(value)? {
            issue(
                issues,
                INVENTORY,
                format!("preserved non-card is missing: {value}"),
            )?;
            continue;
        }
        let text = s.text(value)?.unwrap();
        if value == "docs/AGENTS_ROOT_REFERENCE.md"
            && (!text.contains("../AGENTS.md") || !text.contains("competing root"))
        {
            issue(
                issues,
                value,
                "preserved root reference must point to live root and reject competing-root authority",
            )?;
        }
    }
    for entry in inventory["influencing_surfaces"]
        .as_array()
        .ok_or_else(|| invalid("expected influencing array"))?
    {
        let value = field(entry, "path")?;
        if !s.exists(value)? {
            issue(
                issues,
                INVENTORY,
                format!("influencing surface is missing: {value}"),
            )?;
        }
    }
    let mut ids = BTreeSet::new();
    let tasks = inventory["task_routes"]
        .as_array()
        .ok_or_else(|| invalid("expected tasks"))?;
    if tasks.len() > 4096 {
        return Err(invalid("route task bound exceeded"));
    }
    for task in tasks {
        let id = task.get("id").and_then(Value::as_str).unwrap_or("");
        if id.len() > 4096 {
            return Err(invalid("route task ID byte bound exceeded"));
        }
        if id.is_empty() || !ids.insert(id) {
            issue(
                issues,
                INVENTORY,
                format!(
                    "task route id is missing or duplicated: {}",
                    if id.is_empty() { "<empty>" } else { id }
                ),
            )?;
        }
        for key in [
            "target",
            "owner_route",
            "on_demand_surfaces",
            "validation_paths",
            "completion_evidence",
            "handoff_routes",
        ] {
            let values = match task.get(key) {
                None => Vec::new(),
                Some(Value::String(v)) => vec![v.clone()],
                Some(v) => strings(v)?,
            };
            for value in values {
                if !value.is_empty() && !value.starts_with("aoa-") && !s.exists(&value)? {
                    issue(
                        issues,
                        INVENTORY,
                        format!("task {id} {key} points to missing path: {value}"),
                    )?;
                }
            }
        }
    }
    let current = field(inventory, "currentness")?;
    if !s.is_file(current)? {
        issue(
            issues,
            current,
            "generated AGENTS route currentness is missing",
        )?;
    } else {
        let expected = tracked
            .ok_or_else(|| invalid("Git unavailable for currentness"))
            .and_then(|t| build_from_sources(s, inventory, t))
            .and_then(|v| render_currentness(&v));
        match expected {
            Ok(expected) => {
                if s.text(current)?.as_deref() != Some(&expected) {
                    issue(
                        issues,
                        current,
                        "generated AGENTS route currentness is stale",
                    )?;
                }
            }
            Err(e) => issue(
                issues,
                current,
                format!("cannot verify generated currentness: {e}"),
            )?,
        }
    }
    Ok(())
}
/// The maintained diagnostic order: card shape, inventory/currentness, script refs,
/// then procedural structure. Malformed inventory falls back only for discovery.
pub fn run_validation(root: &Path, cancel: &AtomicI32) -> io::Result<Vec<Issue>> {
    let mut s = RouteSources::new(root)?;
    let inventory = s.inventory();
    if let Err(error) = &inventory {
        let message = error.to_string();
        if !message.starts_with("route inventory is missing")
            && !message.starts_with("route inventory is unreadable or malformed")
            && message != "route input is not UTF-8"
        {
            return Err(invalid(message));
        }
    }
    let discovery = inventory
        .as_ref()
        .ok()
        .filter(|v| v["route_card_discovery"]["route_roots"].is_array());
    let fallback =
        json!({"route_card_discovery":{"root_cards":["AGENTS.md"],"route_roots":DEFAULT_ROOTS}});
    // Validator uses fixed root AGENTS.md even if inventory root_cards differs.
    let mut discovery = match discovery {
        Some(value) => {
            let roots = strings(&value["route_card_discovery"]["route_roots"])?;
            json!({"route_card_discovery":{"root_cards":["AGENTS.md"],"route_roots":roots}})
        }
        None => fallback,
    };
    discovery["route_card_discovery"]["root_cards"] = json!(["AGENTS.md"]);
    let cards = s.discover(&discovery)?;
    let mut issues = Vec::new();
    let p = Patterns::new()?;
    for card in &cards {
        let text = s.text(card)?.ok_or_else(|| invalid("card disappeared"))?;
        card_issues(&mut s, card, &text, &mut issues)?;
    }
    match inventory {
        Ok(inventory) => {
            let tracked = tracked(root, cancel)?;
            inventory_issues(&mut s, &inventory, &cards, tracked.as_ref(), &mut issues)?;
        }
        Err(_) => {
            let message = if s.is_file(INVENTORY)? {
                "route inventory is unreadable or malformed"
            } else {
                "route inventory is missing"
            };
            issue(&mut issues, INVENTORY, message)?;
        }
    }
    for card in &cards {
        let text = s.text(card)?.unwrap();
        for m in p.script.find_iter(&text) {
            let before = text[..m.start()].chars().next_back();
            if before.is_some_and(|c| python_word(c) || matches!(c, '.' | '/')) {
                continue;
            }
            let reference = m.as_str().trim_end_matches(['.', ',', ':', ';']);
            if !s.is_file(reference)? {
                issue(
                    &mut issues,
                    card,
                    format!("local executable reference points to missing path: {reference}"),
                )?;
            }
        }
    }
    let discovered = cards.iter().cloned().collect();
    for card in &cards {
        let mut inherited = false;
        for ancestor in stack(card, false, &discovered, true) {
            inherited |= s
                .text(&ancestor)?
                .is_some_and(|t| t.contains("VALIDATION.md"));
        }
        procedural_issues(card, &s.text(card)?.unwrap(), inherited, &p, &mut issues)?;
        s.check()?;
    }
    Ok(issues)
}
/// Explicit bounded output destination, retaining nofollow directory descriptors.
/// Missing parents are created only under the caller's chosen destination.
pub fn write_output(root: &Path, path: &Path, rendered: &str) -> io::Result<()> {
    if rendered.len() > MAX_OUTPUT {
        return Err(invalid("route output byte bound exceeded"));
    }
    let path = if path.is_absolute() {
        path.to_owned()
    } else {
        root.join(path)
    };
    if path.as_os_str().len() > 4096
        || path
            .components()
            .any(|c| !matches!(c, Component::RootDir | Component::Normal(_)))
    {
        return Err(invalid("invalid route output path"));
    }
    #[cfg(target_os = "linux")]
    {
        use std::os::fd::{AsRawFd, FromRawFd};
        use std::os::unix::ffi::OsStrExt;
        use std::os::unix::fs::MetadataExt;
        let parts: Vec<_> = path
            .components()
            .filter_map(|c| {
                if let Component::Normal(s) = c {
                    Some(s)
                } else {
                    None
                }
            })
            .collect();
        if parts.is_empty() || parts.len() > 128 {
            return Err(invalid("invalid route output depth"));
        }
        let mut dir = File::open("/")?;
        for part in &parts[..parts.len() - 1] {
            let name =
                std::ffi::CString::new(part.as_bytes()).map_err(|_| invalid("NUL output path"))?;
            let mut fd = unsafe {
                libc::openat(
                    dir.as_raw_fd(),
                    name.as_ptr(),
                    libc::O_RDONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW | libc::O_CLOEXEC,
                )
            };
            if fd < 0 && io::Error::last_os_error().kind() == io::ErrorKind::NotFound {
                if unsafe { libc::mkdirat(dir.as_raw_fd(), name.as_ptr(), 0o755) } < 0
                    && io::Error::last_os_error().kind() != io::ErrorKind::AlreadyExists
                {
                    return Err(io::Error::last_os_error());
                }
                fd = unsafe {
                    libc::openat(
                        dir.as_raw_fd(),
                        name.as_ptr(),
                        libc::O_RDONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW | libc::O_CLOEXEC,
                    )
                };
            }
            if fd < 0 {
                return Err(io::Error::last_os_error());
            }
            dir = unsafe { File::from_raw_fd(fd) };
        }
        let name = std::ffi::CString::new(parts.last().unwrap().as_bytes())
            .map_err(|_| invalid("NUL output path"))?;
        let fd = unsafe {
            libc::openat(
                dir.as_raw_fd(),
                name.as_ptr(),
                libc::O_WRONLY
                    | libc::O_CREAT
                    | libc::O_NOFOLLOW
                    | libc::O_NONBLOCK
                    | libc::O_CLOEXEC,
                0o644,
            )
        };
        if fd < 0 {
            return Err(io::Error::last_os_error());
        }
        let mut file = unsafe { File::from_raw_fd(fd) };
        let meta = file.metadata()?;
        if !meta.is_file() || meta.len() > MAX_OUTPUT as u64 || meta.nlink() > 1 {
            return Err(invalid(
                "route output must be a bounded unshared regular file",
            ));
        }
        file.set_len(0)?;
        file.write_all(rendered.as_bytes())?;
        file.flush()
    }
    #[cfg(not(target_os = "linux"))]
    {
        let _ = path;
        Err(io::Error::new(
            io::ErrorKind::Unsupported,
            "route output requires Linux descriptor custody",
        ))
    }
}
/// Read an explicit external/relative output without following any component.
pub fn read_output(path: &Path) -> io::Result<Option<String>> {
    if !path.is_absolute() {
        return Err(invalid("output read requires absolute path"));
    }
    let relative = path
        .strip_prefix("/")
        .map_err(io::Error::other)?
        .to_str()
        .ok_or_else(|| invalid("non-UTF-8 output path"))?;
    let mut sources = RouteSources::new(Path::new("/"))?;
    let Some(file) = sources.open(relative)? else {
        return Ok(None);
    };
    let metadata = file.metadata()?;
    if !metadata.is_file() {
        return Ok(None);
    }
    if metadata.len() > MAX_OUTPUT as u64 {
        return Err(invalid("route output read byte bound exceeded"));
    }
    let mut raw = Vec::with_capacity(metadata.len() as usize);
    file.take(MAX_OUTPUT as u64 + 1).read_to_end(&mut raw)?;
    if raw.len() > MAX_OUTPUT || raw.len() as u64 != metadata.len() {
        return Err(invalid("route output changed or exceeded byte bound"));
    }
    let text = String::from_utf8(raw).map_err(io::Error::other)?;
    Ok(Some(text.replace("\r\n", "\n").replace('\r', "\n")))
}
fn charge_operations(operations: &AtomicUsize, count: usize) -> io::Result<()> {
    operations
        .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |used| {
            used.checked_add(count)
                .filter(|total| *total <= MAX_OPERATIONS)
        })
        .map(|_| ())
        .map_err(|_| invalid("route lookup operation bound exceeded"))
}
#[cfg(target_os = "linux")]
fn open_root(
    root: &Path,
    deadline: Instant,
    operations: &AtomicUsize,
    component_opens: &Cell<usize>,
) -> io::Result<File> {
    use std::os::fd::{AsRawFd, FromRawFd};
    use std::os::unix::ffi::OsStrExt;
    if Instant::now() >= deadline {
        return Err(invalid("route operation deadline exceeded"));
    }
    // The absolute anchor is an actual open too: exhaust/deadline refusal
    // precedes it rather than allowing an uncharged extra descriptor.
    charge_operations(operations, 1)?;
    component_opens.set(
        component_opens
            .get()
            .checked_add(1)
            .filter(|n| *n <= MAX_OPERATIONS)
            .ok_or_else(|| invalid("route root component operation bound exceeded"))?,
    );
    let mut dir = File::open("/")?;
    for part in root.components() {
        if let Component::Normal(part) = part {
            if Instant::now() >= deadline {
                return Err(invalid("route operation deadline exceeded"));
            }
            charge_operations(operations, 1)?;
            let count = component_opens
                .get()
                .checked_add(1)
                .filter(|n| *n <= MAX_OPERATIONS)
                .ok_or_else(|| invalid("route root component operation bound exceeded"))?;
            component_opens.set(count);
            let name =
                std::ffi::CString::new(part.as_bytes()).map_err(|_| invalid("NUL root path"))?;
            let fd = unsafe {
                libc::openat(
                    dir.as_raw_fd(),
                    name.as_ptr(),
                    libc::O_RDONLY | libc::O_DIRECTORY | libc::O_NOFOLLOW | libc::O_CLOEXEC,
                )
            };
            if fd < 0 {
                return Err(io::Error::last_os_error());
            }
            dir = unsafe { File::from_raw_fd(fd) };
        }
    }
    Ok(dir)
}
#[cfg(not(target_os = "linux"))]
fn open_root(
    _root: &Path,
    _deadline: Instant,
    _operations: &AtomicUsize,
    _component_opens: &Cell<usize>,
) -> io::Result<File> {
    Err(io::Error::new(
        io::ErrorKind::Unsupported,
        "route source requires Linux descriptor custody",
    ))
}
/// Conservative pre-copy accounting for pretty JSON fields and containers.
/// The byte bound covers constructed logical output, not allocator/RSS overhead.
pub struct OutputBudget {
    used: usize,
}
impl Default for OutputBudget {
    fn default() -> Self {
        Self::new()
    }
}
impl OutputBudget {
    pub fn new() -> Self {
        Self { used: 0 }
    }
    pub fn reserve(&mut self, bytes: usize) -> io::Result<()> {
        self.used = self
            .used
            .checked_add(bytes)
            .filter(|n| *n <= MAX_OUTPUT)
            .ok_or_else(|| invalid("route pre-copy output budget exceeded"))?;
        Ok(())
    }
    pub fn text(&mut self, text: &str) -> io::Result<()> {
        self.reserve(
            text.len()
                .checked_mul(6)
                .and_then(|n| n.checked_add(258))
                .ok_or_else(|| invalid("route text size overflow"))?,
        )
    }
    pub fn value(&mut self, value: &Value) -> io::Result<()> {
        fn walk(b: &mut OutputBudget, v: &Value, depth: usize) -> io::Result<()> {
            if depth > 128 {
                return Err(invalid("route pre-copy output depth exceeded"));
            }
            b.reserve(258)?;
            match v {
                Value::String(s) => b.text(s)?,
                Value::Object(m) => {
                    for (k, v) in m {
                        b.text(k)?;
                        walk(b, v, depth + 1)?;
                    }
                }
                Value::Array(a) => {
                    for v in a {
                        walk(b, v, depth + 1)?;
                    }
                }
                Value::Number(n) => b.reserve(n.as_str().len().saturating_mul(6))?,
                _ => b.reserve(8)?,
            }
            Ok(())
        }
        walk(self, value, 0)
    }
}
fn is_line_separator(c: char) -> bool {
    matches!(
        c,
        '\n' | '\r'
            | '\u{b}'
            | '\u{c}'
            | '\u{1c}'
            | '\u{1d}'
            | '\u{1e}'
            | '\u{85}'
            | '\u{2028}'
            | '\u{2029}'
    )
}
fn line_count(text: &str) -> usize {
    let mut count = 0;
    let mut chars = text.chars().peekable();
    let mut trailing = false;
    while let Some(c) = chars.next() {
        trailing = is_line_separator(c);
        if trailing {
            count += 1;
            if c == '\r' && chars.peek() == Some(&'\n') {
                chars.next();
            }
        }
    }
    count + usize::from(!text.is_empty() && !trailing)
}
fn python_word(c: char) -> bool {
    c == '_'
        || matches!(
            get_general_category(c),
            GeneralCategory::UppercaseLetter
                | GeneralCategory::LowercaseLetter
                | GeneralCategory::TitlecaseLetter
                | GeneralCategory::ModifierLetter
                | GeneralCategory::OtherLetter
                | GeneralCategory::DecimalNumber
                | GeneralCategory::LetterNumber
                | GeneralCategory::OtherNumber
        )
}
fn word_boundary(text: &str, start: usize, end: usize) -> bool {
    !text[..start].chars().next_back().is_some_and(python_word)
        && !text[end..].chars().next().is_some_and(python_word)
}
fn word_match(pattern: &Regex, text: &str) -> bool {
    pattern
        .find_iter(text)
        .any(|m| word_boundary(text, m.start(), m.end()))
}
fn has_readme_route(p: &Patterns, text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    p.readme.find_iter(text).any(|action| {
        word_boundary(text, action.start(), action.end())
            && lower[action.end()..]
                .match_indices("readme")
                .any(|(index, _)| {
                    let start = action.end() + index;
                    word_boundary(text, start, start + 6)
                })
    })
}

fn lower(text: &str) -> io::Result<String> {
    python_lower_unicode16_v1(text, 8192, 16384, 32768)
        .map_err(|e| invalid(format!("route lowercase: {e:?}")))
}
fn python_printable(c: char) -> bool {
    c == ' '
        || !matches!(
            get_general_category(c),
            GeneralCategory::Control
                | GeneralCategory::Format
                | GeneralCategory::Surrogate
                | GeneralCategory::PrivateUse
                | GeneralCategory::Unassigned
                | GeneralCategory::LineSeparator
                | GeneralCategory::ParagraphSeparator
                | GeneralCategory::SpaceSeparator
        )
}
fn json_preflight(text: &str) -> io::Result<()> {
    let mut quoted = false;
    let mut escaped = false;
    let mut punctuation = 0usize;
    for byte in text.bytes() {
        if quoted {
            if escaped {
                escaped = false;
            } else if byte == b'\\' {
                escaped = true;
            } else if byte == b'"' {
                quoted = false;
            }
        } else if byte == b'"' {
            quoted = true;
        } else if matches!(byte, b'{' | b'}' | b'[' | b']' | b',' | b':') {
            punctuation += 1;
            if punctuation > 100_000 {
                return Err(invalid("route inventory structural token bound exceeded"));
            }
        }
    }
    Ok(())
}

#[cfg(all(test, target_os = "linux"))]
mod foundation_custody_cases {
    use super::*;
    use std::os::unix::fs::symlink;

    #[test]
    fn related_roots_exhaust_one_allowance_before_another_anchor_open() {
        let deadline = Instant::now() + Duration::from_secs(1);
        let primary = RouteSources::new_until(Path::new("/"), deadline).expect("primary root");
        let related = RouteSources::new_until_related(Path::new("/"), deadline, &primary)
            .expect("separately held related root");
        assert!(Arc::ptr_eq(&primary.operations, &related.operations));
        assert_eq!(primary.operation_count(), 2);
        assert_eq!(related.operation_count(), 2);
        let custody = primary.root_custody();
        let related_opens = related.root_component_open_count();
        let operations_before = primary.operation_count();
        assert!(related.verify_custody(&custody).is_err());
        assert_eq!(related.root_component_open_count(), related_opens);
        assert_eq!(primary.operation_count(), operations_before);
        primary
            .verify_custody(&custody)
            .expect("original held root");
        primary
            .operations
            .store(MAX_OPERATIONS - 1, Ordering::Relaxed);
        primary.verify_root().expect("last admitted anchor");
        let before = related.root_component_open_count();
        assert!(related.verify_root().is_err());
        assert_eq!(related.root_component_open_count(), before);
        assert_eq!(primary.operation_count(), MAX_OPERATIONS);
        assert_eq!(related.operation_count(), MAX_OPERATIONS);
        assert!(RouteSources::new_until_related(Path::new("/"), deadline, &primary).is_err());
        assert_eq!(primary.operation_count(), MAX_OPERATIONS);
    }

    #[test]
    fn related_root_cannot_extend_clock_or_receive_a_reset_budget() {
        let deadline = Instant::now() + Duration::from_secs(1);
        let primary = RouteSources::new_until(Path::new("/"), deadline).expect("primary root");
        let before = primary.operation_count();
        assert!(
            RouteSources::new_until_related(
                Path::new("/"),
                deadline + Duration::from_secs(1),
                &primary,
            )
            .is_err()
        );
        assert_eq!(primary.operation_count(), before);
    }

    #[test]
    fn exhausted_root_budget_refuses_before_anchor_or_component_open() {
        let operations = AtomicUsize::new(MAX_OPERATIONS);
        let opens = Cell::new(0);
        let error = open_root(
            Path::new("/tos-route-custody-absent-probe"),
            Instant::now() + Duration::from_secs(1),
            &operations,
            &opens,
        )
        .err()
        .expect("exhausted root walk must refuse");
        assert_eq!(error.kind(), io::ErrorKind::InvalidData);
        assert_eq!(operations.load(Ordering::Relaxed), MAX_OPERATIONS);
        assert_eq!(opens.get(), 0);
        let operations = AtomicUsize::new(MAX_OPERATIONS - 1);
        let opens = Cell::new(0);
        let error = open_root(
            Path::new("/tos-route-custody-absent-probe"),
            Instant::now() + Duration::from_secs(1),
            &operations,
            &opens,
        )
        .err()
        .expect("component exhaustion must precede absent target open");
        assert_eq!(error.kind(), io::ErrorKind::InvalidData);
        assert_eq!(operations.load(Ordering::Relaxed), MAX_OPERATIONS);
        assert_eq!(opens.get(), 1); // only the admitted absolute anchor
    }

    #[test]
    fn expired_root_deadline_refuses_before_anchor_open() {
        let operations = AtomicUsize::new(0);
        let opens = Cell::new(0);
        let error = open_root(
            Path::new("/tos-route-custody-absent-probe"),
            Instant::now(),
            &operations,
            &opens,
        )
        .err()
        .expect("expired root walk must refuse");
        assert_eq!(error.kind(), io::ErrorKind::InvalidData);
        assert_eq!(operations.load(Ordering::Relaxed), 0);
        assert_eq!(opens.get(), 0);
    }

    #[test]
    fn replacement_symlink_changes_topology_even_with_same_endpoint() {
        struct Root(PathBuf);
        impl Drop for Root {
            fn drop(&mut self) {
                let _ = fs::remove_dir_all(&self.0);
            }
        }
        let nonce = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let root = Root(
            std::env::temp_dir().join(format!("tos-route-custody-{}-{nonce}", std::process::id())),
        );
        fs::create_dir(&root.0).expect("exclusive test root");
        fs::write(root.0.join("target"), b"bounded fixture").expect("target");
        symlink("target", root.0.join("selected")).expect("selected link");
        let absolute = fs::canonicalize(&root.0).expect("absolute test root");
        let mut sources = RouteSources::new(&absolute).expect("held test root");
        let before = match sources
            .resolve_selected_target("selected", None)
            .expect("resolve")
        {
            RouteResolvedTarget::Inside {
                relative_path,
                topology_stamp,
                metadata: Some(m),
            } => {
                assert_eq!(relative_path, "target");
                assert!(m.is_file());
                topology_stamp
            }
            _ => panic!("selected test link must resolve inside"),
        };
        fs::remove_file(root.0.join("selected")).expect("replace selected link");
        symlink("./target", root.0.join("selected")).expect("replacement link");
        match sources
            .resolve_selected_target("selected", None)
            .expect("resolve replacement")
        {
            RouteResolvedTarget::Inside {
                relative_path,
                topology_stamp,
                metadata: Some(m),
            } => {
                assert_eq!(relative_path, "target");
                assert!(m.is_file());
                assert_ne!(before, topology_stamp);
            }
            _ => panic!("replacement test link must resolve inside"),
        }
    }
}
